-- BRUVIFIT: exemplos sintéticos, lote BFDEV26A; MySQL 8, execução MANUAL.
-- NÃO é migration. Não executado pela aplicação. Não há DDL nem atualização/exclusão.
-- Antes: confirme conexão localhost/127.0.0.1, ambiente DESENVOLVIMENTO e schema.
-- Faça backup no Workbench: Server > Data Export > bruvifit > Export to Self-Contained File.
-- Confira SHOW CREATE TABLE de todas as tabelas abaixo contra database.sql.
-- Execute em uma única conexão, sem concorrência e com STOP ON ERROR.
-- Se ocorrer QUALQUER erro: execute ROLLBACK; não continue nem confirme parcialmente.
-- Este script termina SEM COMMIT. Inspecione os resultados e confirme manualmente.
-- Somente após conferir host/schema/backup, altere o valor seguinte para 1.
SET @confirm_local_development=0;
SET SESSION time_zone='-03:00';
SET NAMES utf8mb4;
SELECT DATABASE() banco, @@hostname servidor, @@port porta, VERSION() versao;
SELECT TABLE_NAME, ENGINE FROM information_schema.tables WHERE table_schema=DATABASE()
AND table_name IN ('cliente','fornecedor','produto','pedido','item_pedido','financeiro','estoque','produto_fornecedor');
-- Exige InnoDB para rollback e ausência de triggers nessas tabelas.
-- Havendo triggers, revisar seus efeitos antes de adaptar/executar o lote.
SET @actor=(SELECT MIN(id) FROM usuario WHERE ativo=1 AND aprovado=1);
SET @seed_now=NOW();
START TRANSACTION;
SET @seed_ok=(@confirm_local_development=1 AND DATABASE()='bruvifit' AND @actor IS NOT NULL
 AND (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND engine='InnoDB'
 AND table_name IN ('cliente','fornecedor','produto','pedido','item_pedido','financeiro','estoque','produto_fornecedor'))=8
 AND NOT EXISTS(SELECT 1 FROM information_schema.triggers WHERE trigger_schema=DATABASE() AND event_object_table IN ('cliente','fornecedor','produto','pedido','item_pedido','financeiro','estoque','produto_fornecedor'))
 AND NOT EXISTS(SELECT 1 FROM produto WHERE sku LIKE 'BFDEV26A-%')
 AND NOT EXISTS(SELECT 1 FROM cliente WHERE email LIKE 'bfdev26a.%@example.invalid')
 AND NOT EXISTS(SELECT 1 FROM fornecedor WHERE email LIKE 'bfdev26a.%@example.invalid')
 AND NOT EXISTS(SELECT 1 FROM pedido WHERE chave_requisicao LIKE 'BFDEV26A-%'));
SELECT @seed_ok autorizado_e_lote_novo;
SELECT 'ANTES' fase,(SELECT COUNT(*) FROM cliente) clientes,(SELECT COUNT(*) FROM fornecedor) fornecedores,
(SELECT COUNT(*) FROM produto) produtos,(SELECT COUNT(*) FROM pedido) pedidos,
(SELECT COUNT(*) FROM item_pedido) itens,(SELECT COUNT(*) FROM financeiro) financeiro,(SELECT COUNT(*) FROM estoque) estoque;
-- Uma nova execução reconhece os marcadores e insere ZERO registros.
-- Produtos não possuem data de cadastro no schema: não é possível demonstrar idade/baixo giro.

