-- Validações finais: todas as consultas de inconsistência devem retornar ZERO linhas.
SELECT pe.id,pe.valor_total,SUM(i.subtotal) itens FROM pedido pe JOIN item_pedido i ON i.pedido_id=pe.id
WHERE pe.chave_requisicao LIKE 'BFDEV26A-%' GROUP BY pe.id,pe.valor_total HAVING pe.valor_total<>SUM(i.subtotal);
SELECT p.id,p.saldo_estoque,SUM(CASE e.tipo WHEN 'ENTRADA' THEN e.quantidade ELSE -e.quantidade END) saldo_ledger
FROM produto p JOIN estoque e ON e.produto_id=p.id WHERE p.sku LIKE 'BFDEV26A-%'
GROUP BY p.id,p.saldo_estoque HAVING p.saldo_estoque<>saldo_ledger;
SELECT f.pedido_id FROM financeiro f JOIN pedido pe ON pe.id=f.pedido_id
WHERE pe.chave_requisicao LIKE 'BFDEV26A-%' GROUP BY f.pedido_id,pe.valor_total HAVING SUM(f.valor)>pe.valor_total;
SELECT 'DEPOIS' fase,(SELECT COUNT(*) FROM cliente) clientes,(SELECT COUNT(*) FROM fornecedor) fornecedores,
(SELECT COUNT(*) FROM produto) produtos,(SELECT COUNT(*) FROM pedido) pedidos,
(SELECT COUNT(*) FROM item_pedido) itens,(SELECT COUNT(*) FROM financeiro) financeiro,(SELECT COUNT(*) FROM estoque) estoque;
